import{_ as a,a as d}from"./chunks/racquet_detail.5lhaXGbQ.js";import{_ as r,o as e,c as o,a0 as l}from"./chunks/framework.akKRIpjQ.js";const p=JSON.parse('{"title":"03 · 球拍档案","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/03-racquets.md","filePath":"zh/guide/03-racquets.md"}'),i={name:"zh/guide/03-racquets.md"};function h(n,t,s,u,c,b){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="_03-·-球拍档案" tabindex="-1">03 · 球拍档案 <a class="header-anchor" href="#_03-·-球拍档案" aria-label="Permalink to &quot;03 · 球拍档案&quot;">​</a></h1><blockquote><p>4 个功能中的第 2 个。记录你拥有的每一支球拍 —— 品牌、型号、拍面、长度、重量、平衡点、目标磅数 —— 全部本地保存。</p></blockquote><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><img src="'+a+'" alt="球拍列表" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>「球拍」Tab 是一个&quot;球拍集合&quot;页。每一张卡片显示该球拍（如设置了）的照片和一行汇总：</p><ul><li>封面照片（选填）</li><li>球拍名</li><li>品牌 · 型号</li><li>拍面</li><li>上次穿线日期</li></ul><p><code>+ 添加球拍</code> 打开表单；卡片菜单提供 <code>编辑 / 删除 / 设置提醒</code>。</p><h2 id="添加一支球拍" tabindex="-1">添加一支球拍 <a class="header-anchor" href="#添加一支球拍" aria-label="Permalink to &quot;添加一支球拍&quot;">​</a></h2><ol><li>「球拍」Tab → <code>+ 添加球拍</code></li><li>填表（最少 4 项，其余可空）：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>是否必填</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>✅</td><td>例 &quot;主力 Blade&quot; / &quot;备用 Pro Staff&quot;</td></tr><tr><td>品牌</td><td>✅</td><td>下拉；找不到可自填</td></tr><tr><td>型号</td><td>✅</td><td>下拉；找不到可自填</td></tr><tr><td>拍面</td><td>✅</td><td>数字 + 单位（默认 in²）</td></tr><tr><td>长度</td><td>❌</td><td>默认 27&quot;</td></tr><tr><td>空拍重量</td><td>❌</td><td>g 或 oz</td></tr><tr><td>平衡点</td><td>❌</td><td>mm 或 in</td></tr><tr><td>穿线磅数主 / 横</td><td>❌</td><td>主磅 / 横磅，留空以后填</td></tr><tr><td>备注</td><td>❌</td><td>&quot;生日礼物 / 2019 年购入&quot;等</td></tr><tr><td>封面照片</td><td>❌</td><td>从相册选或现拍</td></tr></tbody></table><ol start="3"><li><code>保存</code></li></ol><blockquote><p>已添加的拍子在「球拍」Tab 列表里以卡片显示。</p></blockquote><h2 id="详情页" tabindex="-1">详情页 <a class="header-anchor" href="#详情页" aria-label="Permalink to &quot;详情页&quot;">​</a></h2><img src="'+d+'" alt="球拍详情页" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>点击任意一张卡片进入详情页。四个 Tab：</p><table tabindex="0"><thead><tr><th>Tab</th><th>你在这里做什么</th></tr></thead><tbody><tr><td><strong>档案</strong></td><td>球拍规格（只读展示；点 <code>编辑</code> 修改）</td></tr><tr><td><strong>穿线记录</strong></td><td>全部穿线记录（见 <a href="./04-stringing-log.html">04 · 穿线记录</a>）</td></tr><tr><td><strong>提醒</strong></td><td>设置或编辑换线提醒（见 <a href="./04-stringing-log.html#换线提醒">04 · 穿线记录</a>）</td></tr><tr><td><strong>备注</strong></td><td>你加的自由文本备注</td></tr></tbody></table><p>详情页右上角有 <code>编辑</code> 按钮；更多菜单里有 <code>删除</code>。</p><h2 id="规格怎么填" tabindex="-1">规格怎么填? <a class="header-anchor" href="#规格怎么填" aria-label="Permalink to &quot;规格怎么填?&quot;">​</a></h2><h3 id="拍面-head-size" tabindex="-1">拍面（Head Size） <a class="header-anchor" href="#拍面-head-size" aria-label="Permalink to &quot;拍面（Head Size）&quot;">​</a></h3><p>V1.0 默认单位是<strong>平方英寸</strong>。常见值速查：</p><table tabindex="0"><thead><tr><th>拍面 (in²)</th><th>类型</th></tr></thead><tbody><tr><td>95–98</td><td>控球型（小拍面）</td></tr><tr><td>98–100</td><td>中性</td></tr><tr><td>100–104</td><td>容错型</td></tr><tr><td>104–115</td><td>大拍面 / 休闲</td></tr></tbody></table><blockquote><p><strong>注</strong>：上面 4 档只用来<strong>判断打法风格</strong>。在 <a href="./05-tension-conversion.html#拍面档位dt--rt-用">05 · 张力换算</a> 里， App 把所有拍面归并为 <strong>3 档</strong>（与 ERT300 穿线机的 DT 锚点表一致）—— <strong>MID 83–94 / MID+ 95–105 / OVER 106–115 平方英寸</strong>（或 cm²：540–610 / 611–680 / 681–740）。 进张力换算时只要选对档就行，不用回头找精确数字。</p></blockquote><h3 id="空拍重量-strung-weight" tabindex="-1">空拍重量（Strung Weight） <a class="header-anchor" href="#空拍重量-strung-weight" aria-label="Permalink to &quot;空拍重量（Strung Weight）&quot;">​</a></h3><p>需要自己上网查&quot;该型号规格&quot;，一般给「strung weight」。</p><table tabindex="0"><thead><tr><th>范围 (g)</th><th>风格</th></tr></thead><tbody><tr><td>&lt; 300</td><td>极轻（攻击型）</td></tr><tr><td>300–320</td><td>标准</td></tr><tr><td>320–340</td><td>控球型</td></tr><tr><td>&gt; 340</td><td>重量型</td></tr></tbody></table><h3 id="平衡点-balance" tabindex="-1">平衡点（Balance） <a class="header-anchor" href="#平衡点-balance" aria-label="Permalink to &quot;平衡点（Balance）&quot;">​</a></h3><ul><li>用 mm（更精确）或 in</li><li>一般拍子在 320–340 mm（&quot;even balance&quot; ~ 320 mm；&quot;head light&quot; 偏小；&quot;head heavy&quot; 偏大）</li></ul><h2 id="为什么要做-档案" tabindex="-1">为什么要做&quot;档案&quot;? <a class="header-anchor" href="#为什么要做-档案" aria-label="Permalink to &quot;为什么要做&quot;档案&quot;?&quot;">​</a></h2><ul><li><strong>一次录入</strong>：下次穿线记录会自动带入主磅 / 横磅、拍面等</li><li><strong>提醒上下文</strong>：提醒知道是哪支拍该换线了（&quot;主力 Blade 该换线了&quot;）</li><li><strong>封面照片</strong>：球拍多了之后一眼可辨</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="我有-10-支拍-卡片太多怎么办" tabindex="-1">我有 10 支拍，卡片太多怎么办? <a class="header-anchor" href="#我有-10-支拍-卡片太多怎么办" aria-label="Permalink to &quot;我有 10 支拍，卡片太多怎么办?&quot;">​</a></h3><p>「球拍」Tab 列表支持左右滑动切换卡片（手机）或上下滚动（平板）。长按卡片可&quot;置顶&quot;前 4 张。</p><h3 id="封面照片必须吗" tabindex="-1">封面照片必须吗? <a class="header-anchor" href="#封面照片必须吗" aria-label="Permalink to &quot;封面照片必须吗?&quot;">​</a></h3><p>不必。没设封面的卡片会用品牌首字母占位。</p><h3 id="上次穿线日期-是怎么来的" tabindex="-1">&quot;上次穿线日期&quot;是怎么来的? <a class="header-anchor" href="#上次穿线日期-是怎么来的" aria-label="Permalink to &quot;&quot;上次穿线日期&quot;是怎么来的?&quot;">​</a></h3><p>取该球拍 <a href="./04-stringing-log.html">穿线记录</a> Tab 中<strong>最新一条</strong>的日期。</p><h2 id="下一步" tabindex="-1">下一步? <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步?&quot;">​</a></h2><p>光有档案还差一步 —— 至少录一次穿线，见 <a href="./04-stringing-log.html">04 · 穿线记录</a>。</p><p>或者想先换算一下磅数？看 <a href="./05-tension-conversion.html">05 · 张力换算</a>，DT ⇄ RT ⇄ lbs ⇄ kg 互转；最下方有「用此张力记录穿线」一键跳回第 4 章。</p>',39)])])}const m=r(i,[["render",h]]);export{p as __pageData,m as default};
